function validate([prob, target]) {
  if (prob.length < 1 || prob.length > 1000) return 'prob needs 1 to 1000 coins.';
  if (prob.some(p => typeof p !== 'number' || !(p >= 0 && p <= 1))) return 'Each probability is between 0 and 1.';
  if (!Number.isInteger(target) || target < 0 || target > prob.length) return 'target is a whole number from 0 to prob.length.';
  return null;
}

