function probabilityOfHeads(prob, target) {
  const dp = new Array(target + 1).fill(0);
  dp[0] = 1;

  for (const p of prob) {
    for (let heads = target; heads >= 1; heads--) {
      dp[heads] = dp[heads] * (1 - p) + dp[heads - 1] * p;
    }
    dp[0] = dp[0] * (1 - p);
  }

  return dp[target];
}

