function probabilityOfHeads(prob, target) {
  // Build the full distribution of head counts, one coin at a time, pushing each count forward.
  let dist = [1];
  for (let i = 0; i < prob.length; i++) {
    const grown = new Array(dist.length + 1).fill(0);
    for (let count = 0; count < dist.length; count++) {
      grown[count] += dist[count] * (1 - prob[i]);
      grown[count + 1] += dist[count] * prob[i];
    }
    dist = grown;
  }
  return dist[target] ?? 0;
}

