function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const coin = () => {
    const r = rand();
    if (r < 0.1) return 0;
    if (r < 0.2) return 1;
    if (r < 0.3) return 0.5;
    return Math.round(rand() * 100) / 100;
  };
  if (size === 'small') {
    const n = int(1, 8);
    const prob = Array.from({ length: n }, coin);
    return [prob, int(0, n)];
  }
  const n = int(800, 1000);
  const bias = rand();
  const prob = Array.from({ length: n }, () => Math.round(Math.min(1, Math.max(0, bias + (rand() - 0.5) * 0.6)) * 1000) / 1000);
  const mean = prob.reduce((sum, p) => sum + p, 0);
  const target = Math.min(n, Math.max(0, Math.round(mean) + int(-10, 10)));
  return [prob, target];
}
